import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import gameService from "../../services/gameService";
import WheelGamePreview from '../../img/WheelGamePreview.jpg';
import './GamesPreview.css';

function GamesPreview() {
    // Состояние для данных
    const [games, setGames] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    
    // Если нужно использовать данные пользователя
    const { currentUser } = useAuth();
    
    // Функция загрузки данных
    const loadGames = async () => {
        try {
            setLoading(true);
            setError(null);
            
            const data = await gameService.getUserGames();
            setGames(data.games || []);
            
        } catch (err) {
            setError('Не удалось загрузить игры');
            console.error('Ошибка загрузки:', err);
        } finally {
            setLoading(false);
        }
    };
    
    // Загружаем данные при монтировании
    useEffect(() => {
        loadGames();
    }, []);
    
    // Кнопка обновления
    const refreshGames = () => {
        loadGames();
    };
    
    // Иконки для разных типов игр
    const getGameIcon = (gameType) => {
        switch (gameType) {
            case 'wheel': return '🎡';
            case 'quiz': return '❓';
            case 'match': return '🔗';
            default: return '🎮';
        }
    };
    
    // Обработка состояний
    if (loading) {
        return (
            <div className="games-container">
                <div className="games-loading">
                    <div className="loading-spinner"></div>
                    <p>Загрузка игр...</p>
                </div>
            </div>
        );
    }
    
    if (error) {
        return (
            <div className="games-container">
                <div className="games-error">
                    <h2>Ошибка загрузки</h2>
                    <p>{error}</p>
                    <button onClick={refreshGames} className="retry-button">
                        Повторить
                    </button>
                </div>
            </div>
        );
    }
    
    if (games.length === 0) {
        return (
            <div className="games-container">
                <div className="games-empty">
                    <h2>У вас пока нет сохраненных игр</h2>
                    <p>Создайте свою первую игру в конструкторе</p>
                    <button onClick={refreshGames} className="refresh-button">
                        Обновить
                    </button>
                </div>
            </div>
        );
    }
    
    // Отображение списка игр
    return (
        <div className="games-container">
            <div className="games-header">
                <h1>Мои игры</h1>
                <button onClick={refreshGames} className="refresh-btn">
                    Обновить
                </button>
            </div>
            
            <div className="games-grid">
                {games.map(game => (
                    <div key={game.id} className="game-card">
                        <div className="game-card-header">
                            <span className="game-icon">{getGameIcon(game.game_type)}</span>
                            <span className="game-type">{game.game_type}</span>
                        </div>
                        
                        <div className="game-preview">
                            <img 
                                src={WheelGamePreview} 
                                alt={`${game.game_name} preview`}
                                onError={(e) => {
                                    e.target.style.display = 'none';
                                }}
                            />
                        </div>
                        
                        <div className="game-info">
                            <h3 className="game-title">{game.game_name}</h3>
                            <p className="game-date">
                                {new Date(game.created_at).toLocaleDateString('ru-RU')}
                            </p>
                        </div>
                        
                        <div className="game-actions">
                            <button 
                                className="play-btn"
                                onClick={() => console.log('Играть:', game.id)}
                            >
                                Играть
                            </button>
                            <button 
                                className="delete-btn"
                                onClick={() => {
                                    if (window.confirm('Удалить эту игру?')) {
                                        console.log('Удалить:', game.id);
                                    }
                                }}
                            >
                                Удалить
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default GamesPreview;
